/** TODO: Separate in multiple files, and search how to only have one chunk name in dev mode */
const cacheName = 'cache-app'
const cacheImgName = 'cache-img'
const BASE_URL_IMG = 'https://pub-4211d6b528d54ed69e8ec217f023723e.r2.dev/'
const baseCacheResources = [
	'./',
	'./index.html',
]

/**
 * Open the App IndexedDB and do the migrations
 * @type {Promise<IDBDatabase>}
 */
const getCacheDB = new Promise((resolve, reject) => {
	const request = indexedDB.open('cache', 1)
	request.onupgradeneeded = ev => {
		const db = request.result
		if (!ev.oldVersion) {
			db.createObjectStore('config')
		}
	}
	request.onerror = () => {
		console.error('[indexeddb]', request.error)
		reject(request.error)
	}
	request.onsuccess = ev => {
		resolve(ev.target.result)
	}
})

const lsGetItem = async name => {
	/** @type {IDBDatabase} */
	const db = await getCacheDB
	return new Promise((resolve, reject) => {
		const tr = db.transaction('config', 'readonly')
		tr.onerror = reject
		const store = tr.objectStore('config')
		const req = store.get(name)
		req.onsuccess = ev => {
			resolve(req.result)
		}
	})
}
const lsSetItem = async (name, value) => {
	/** @type {IDBDatabase} */
	const db = await getCacheDB
	return new Promise((resolve, reject) => {
		const tr = db.transaction('config', 'readwrite')
		tr.onerror = reject
		const store = tr.objectStore('config')
		const req = store.put(value, name)
		req.onsuccess = ev => {
			resolve(req.result)
		}
	})
}

const IS_DEV = process.env.NODE_ENV === 'development'

async function clearAndCacheAppFiles() {
	await caches.delete(cacheName)
	return caches.open(cacheName).then(async cache => {
		const manifest = await fetch('manifest.json', { cache: 'no-store' }).then(res => res.json()).catch(() => ({}))
		lsSetItem('version', manifest.VERSION)
		delete manifest.VERSION

		const resources = [
			...baseCacheResources,
			...Object.values(manifest).map(s => s.replace(/^\//, './')),
		].filter((url, idx, arr) => arr.indexOf(url) === idx)
		return cache.addAll(resources).then(async res => {
			console.log(new Date(), 'Cached app version', await lsGetItem('version'))
			return res
		})
	}).then(() => {
		console.log(new Date(), 'added all ressources to cache')
	})
}

/**
 * Return the correct Cache storage from an ext & lang
 * We separate into multiple Cache storage to be able to send efficiently the downloaded card images
 * @param {string} set
 * @param {string} lang
 * @returns {string}
 */
function getCacheSetName(set, lang) {
	return `${cacheImgName}-set-${set}-${lang}`
}

/**
 * Return the correct Cache storage from an URL
 * @param {string} url
 * @returns {Promise<Cache>}
 */
function getCacheFromURL(url) {
	const isImg = url.startsWith(BASE_URL_IMG)
	if (!isImg) return caches.open(cacheName)
	const lastPart = url.split('/').pop().split('?').shift()
	const [, set, lang] = lastPart.match(/^([A-Z0-9]+).+-([a-z]+)-(h|s)d(-c)?.*\.([a-z]+)$/i)
	return caches.open(getCacheSetName(set, lang))
}

// When the service worker is installing, open the cache and add the precache resources to it
self.addEventListener('install', event => {
	self.skipWaiting()
	event.waitUntil(Promise.resolve())
	
	if (IS_DEV) return

	// Cache the app asynchronously
	clearAndCacheAppFiles()
})
self.addEventListener('activate', ev => self.clients.claim())

// When there's an incoming fetch request, try and respond with a precached resource, otherwise fall back to the network
self.addEventListener('fetch', event => {
	const url = event.request.url.toString()
	const isImg = url.startsWith(BASE_URL_IMG)
	if (IS_DEV && !isImg) return fetch(event.request)

	event.respondWith(
		caches.match(event.request).then(async cachedResponse => {
			if (new URL(url).pathname === '/' || new URL(url).pathname === '/index.html') {
				// Checking if cache is accurate
				const currentVersion = await lsGetItem('version')
				const manifest = await fetch('/manifest.json', { cache: 'no-store' }).then(res => res.json()).catch(() => null)
				if (manifest && manifest.VERSION !== currentVersion) {
					console.log(new Date(), 'New version detected, removing cache and getting new files')
					clearAndCacheAppFiles()
					return fetch(event.request)
				}
			}
			if (cachedResponse) {
				return cachedResponse
			}
			const response = await fetch(event.request)
			if (isImg && (response.ok || response.type === 'opaque')) {
				caches.open(cacheImgName).then(cache => cache.add(url)).catch(console.error)
			}
			return response
		}),
	)
})

self.onmessage = async ev => {
	const id = ev.data?.id || undefined
	if ('cache' in ev.data) {
		if (typeof ev.data.cache === 'string') {
			const url = ev.data.cache
			const isImg = url.startsWith(BASE_URL_IMG)
			if (isImg) {
				caches.match(url).then(isCached => {
					if (isCached) return
					getCacheFromURL(url).then(cache => cache.add(url)).catch(console.error)
				})
			}
		} else if (ev.data.cache?.set && ev.data.cache?.lang && ev.data.cache?.urls) {
			return caches.open(getCacheSetName(ev.data.cache?.set, ev.data.cache?.lang)).then(cache => {
				cache.addAll(ev.data.cache?.urls).then(() => {
					ev.source.postMessage({
						id,
						set: ev.data.cache?.set,
						lang: ev.data.cache?.lang,
						cached: ev.data.cache?.urls.length,
						total: ev.data.cache?.urls.length,
					})
				}).catch(err => {
					ev.source.postMessage({
						id,
						set: ev.data.cache?.set,
						lang: ev.data.cache?.lang,
						cached: 0,
						total: ev.data.cache?.urls.length,
						error: err.toString(),
					})
				})
			})
		}
	}
	if ('getCache' in ev.data) {
		if (ev.data.getCache === 'img') {
			caches.open(cacheImgName).then(async cache => {
				ev.source.postMessage({
					id,
					all: true,
					cache: (await cache.keys()).reduce((map, s) => {
						map[s.url] = true
						return map
					}, {}),
				})
			})
		} else if (ev.data.getCache?.set && ev.data.getCache?.lang) {
			caches.open(getCacheSetName(ev.data.getCache?.set, ev.data.getCache?.lang)).then(async cache => {
				ev.source.postMessage({
					id,
					set: ev.data.getCache?.set,
					lang: ev.data.getCache?.lang,
					cache: (await cache.keys()).reduce((map, s) => {
						map[new URL(s.url).pathname] = true
						return map
					}, {}),
				})
			})
		}
	}
	if ('removeCache' in ev.data) {
		if (ev.data.removeCache === 'images') {
			const allCaches = await caches.keys()
			for (const key of allCaches) {
				if (key.startsWith(cacheImgName + '-set-')) caches.delete(key)
			}
		}
	}
}